"""CrankArm_exact: parametric CadQuery model generated by stl2cad (exact mode, 2.5D).

The part is built along +z from 2 extrusion(s) and 2 cut(s), applied in order;
each is an outline in the xy plane between two levels. Units: mm.
Run:  python CrankArm_exact.py [out.step]
"""

import math
import sys

from cadquery import Edge, Vector
from cadquery import func as cf

# ---- parameters ----------------------------------------------------------
z0 = 0.0    # level along z
z1 = 12.7    # level along z
z2 = 25.4    # level along z
hole_d = 12.7

DIR = (0, 0, 1)


def P(a, b):
    """Point (x, y) in the sketch plane (z = 0)."""
    return (a, b, 0)


def prism(outline, lo, hi):
    """Outline extruded from level lo to level hi."""
    body = cf.extrude(cf.face(outline), [(hi - lo) * c for c in DIR])
    return body.translate(Vector(*[lo * c for c in DIR]))


def hole(a, b, d, lo, hi):
    return prism(Edge.makeCircle(d / 2, P(a, b), DIR), lo, hi)


# ---- 1. extrusion: z 0.0 to 12.7 ------------------------------
outline_1 = cf.wire(
    cf.segment(P(15.24, 0.0), P(142.24, 0.0)),
    Edge.makeThreePointArc(P(142.24, 0.0), P(157.48, 15.24), P(142.24, 30.48)),
    cf.segment(P(142.24, 30.48), P(15.24, 30.48)),
    Edge.makeThreePointArc(P(15.24, 30.48), P(0.0, 15.24), P(15.24, 0.0)),
)
part = prism(outline_1, z0, z1)

# ---- 2. extrusion: z 12.7 to 25.4 ------------------------------
outline_2 = cf.wire(
    Edge.makeCircle(10.414, P(15.24, 15.24), DIR),
)
part = part + prism(outline_2, z1, z2)

# ---- round holes: (x, y, diameter, from, to) ------------------------
for a, b, d, lo, hi in [
    (15.24, 15.24, hole_d, z0, z2),
    (142.24, 15.24, hole_d, z0, z1),
]:
    part = part - hole(a, b, d, lo, hi)

part = part.clean()

if __name__ == "__main__":
    part.exportStep(sys.argv[1] if len(sys.argv) > 1 else "CrankArm_exact.step")
